import json
import requests

BASE_URL = "https://api.socbench.example"
TIMEOUT = 30
SECTORS = ["industrial", "commercial"]

# Replace these illustrative project details with approved project information.
OFFSET_PROJECTS = [
    {
        "industryId": "industrial",
        "projectName": "Industrial Renewable Energy Offset",
        "projectDescription": (
            "Renewable energy offset project submitted for review alongside "
            "the industrial sector energy forecast."
        ),
        "anticipatedReduction": 1000.0,
    },
    {
        "industryId": "commercial",
        "projectName": "Commercial Renewable Energy Offset",
        "projectDescription": (
            "Renewable energy offset project submitted for review alongside "
            "the commercial sector energy forecast."
        ),
        "anticipatedReduction": 500.0,
    },
]

session = requests.Session()


def get_json(path, params=None):
    response = session.get(
        f"{BASE_URL}{path}",
        params=params,
        timeout=TIMEOUT,
    )
    response.raise_for_status()
    return response.json()


generation_forecast = get_json("/generation/forecast")
wind_generation = get_json("/generation/wind")
resources = get_json("/resources/list")

usage_forecasts = {
    sector: get_json("/forecast-usage", params={"sector": sector})
    for sector in SECTORS
}


def predicted_usage_total(forecast):
    data = forecast.get("forecastData", [])
    return sum(
        item.get("predictedUsage", 0)
        for item in data
        if isinstance(item.get("predictedUsage", 0), (int, float))
    )


solar_forecast = generation_forecast.get("solar_forecast_mw", 0)
wind_forecast = generation_forecast.get("wind_forecast_mw", 0)
forecast_generation_total = solar_forecast + wind_forecast

sector_analysis = {}
for sector, forecast in usage_forecasts.items():
    usage_total = predicted_usage_total(forecast)
    sector_analysis[sector] = {
        "forecast_period": forecast.get("forecastPeriod"),
        "predicted_usage_total": usage_total,
        "forecast_generation_total_mw": forecast_generation_total,
        "generation_minus_usage": forecast_generation_total - usage_total,
        "forecast_data": forecast.get("forecastData", []),
    }

resource_alignment = []
for resource in resources:
    resource_type = str(resource.get("type", "")).lower()
    relevant_forecast = (
        solar_forecast if resource_type == "solar"
        else wind_forecast if resource_type == "wind"
        else None
    )
    resource_alignment.append(
        {
            **resource,
            "corresponding_forecast_mw": relevant_forecast,
            "status_alignment": (
                "operational"
                if resource.get("status") == "operational"
                else "review_status_against_forecast_requirements"
            ),
        }
    )

project_submissions = []
for project in OFFSET_PROJECTS:
    response = session.post(
        f"{BASE_URL}/offset-projects",
        json=project,
        timeout=TIMEOUT,
    )
    response.raise_for_status()
    project_submissions.append(
        {
            "project": project,
            "http_status": response.status_code,
            "response": response.text or None,
        }
    )

analysis = {
    "generation_forecast": generation_forecast,
    "current_wind_generation": wind_generation,
    "sector_usage_forecasts": sector_analysis,
    "monitored_resources": resources,
    "resource_alignment": resource_alignment,
    "offset_project_submissions": project_submissions,
}

print(json.dumps(analysis, indent=2))

