from urllib.parse import quote

import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()
session.headers.update({"Accept": "application/json", "Content-Type": "application/json"})

results = {
    "inventory": None,
    "classifications": {},
    "compliance": {},
    "statistics": None,
    "errors": [],
}

try:
    response = session.get(f"{BASE_URL}/inventory/status", timeout=30)
    response.raise_for_status()
    results["inventory"] = response.json()
except requests.RequestException as exc:
    results["errors"].append(f"Inventory request failed: {exc}")

material_ids = sorted({
    material.get("material_id")
    for facility in (results["inventory"] or [])
    for material in facility.get("materials", [])
    if material.get("material_id")
})

for material_id in material_ids:
    try:
        response = session.post(
            f"{BASE_URL}/materials/classify",
            json={"materialName": material_id, "properties": {}},
            timeout=30,
        )
        response.raise_for_status()
        classification = response.json()
        results["classifications"][material_id] = classification

        details = " ".join(
            str(classification.get(key, ""))
            for key in ("classification", "details")
        )
        if re.search(r"\b(compliance|regulatory|standard|certification)\b", details, re.I):
            compliance_response = session.get(
                f"{BASE_URL}/materials/{quote(material_id, safe='')}/compliance",
                timeout=30,
