            results["compliance"][material_id] = compliance_response.json()
    except requests.RequestException as exc:
        results["errors"].append(f"Processing material {material_id} failed: {exc}")

try:
    response = session.get(f"{BASE_URL}/analysis/statistics", timeout=30)
    response.raise_for_status()
    results["statistics"] = response.json()
except requests.RequestException as exc:
    results["errors"].append(f"Statistics request failed: {exc}")

