import json
import os

import requests

BASE_URL = "https://api.socbench.example"
TIMEOUT = 30

session = requests.Session()
session.headers.update({"Accept": "application/json", "Content-Type": "application/json"})


def get_json(path):
    response = session.get(f"{BASE_URL}{path}", timeout=TIMEOUT)
    response.raise_for_status()
    return response.json()


def post_json(path, payload):
    response = session.post(f"{BASE_URL}{path}", json=payload, timeout=TIMEOUT)
    response.raise_for_status()
    return response.json()


def as_records(value):
    if isinstance(value, list):
        return [item for item in value if isinstance(item, dict)]
    if isinstance(value, dict):
        for key in ("categories", "performance", "metrics", "results", "items"):
            nested = value.get(key)
            if isinstance(nested, list):
                return [item for item in nested if isinstance(item, dict)]
        return [value]
    return []


def first_number(record, keys):
    for key in keys:
        value = record.get(key)
        if isinstance(value, (int, float)):
            return float(value)
    return 0.0


regional_sales = get_json("/regional/sales-comparisons")
category_performance = get_json("/categories/performance")

regions = [
    item for item in regional_sales
    if isinstance(item, dict) and isinstance(item.get("sales"), (int, float))
]
regions.sort(key=lambda item: item["sales"], reverse=True)
high_demand_regions = regions[:5]

category_records = as_records(category_performance)
for record in category_records:
    record["_priority_score"] = (
        first_number(record, ("sales", "revenue", "unitsSold"))
        + first_number(record, ("engagement", "engagements", "views", "clicks"))
    )
category_records.sort(key=lambda record: record["_priority_score"], reverse=True)
top_categories = [
    {key: value for key, value in record.items() if key != "_priority_score"}
    for record in category_records[:5]
]

# Supply listing details as JSON in ROOM_LISTING_JSON if they are available.
# The documented API has no endpoint for creating or submitting room listings.
