import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()


def get_json(path):
    response = session.get(f"{BASE_URL}{path}", timeout=30)
    response.raise_for_status()
    return response.json()


def extract_supply_requirements(value):
    """Find explicitly stated supply requirements in patient records."""
    requirements = []

    if isinstance(value, dict):
        item_id = value.get("item_id")
        item_name = value.get("item_name") or value.get("supply_name")
        quantity = value.get("required_quantity", value.get("quantity_needed"))

        if (item_id or item_name) and isinstance(quantity, (int, float)) and quantity > 0:
            requirements.append({
                "item_id": item_id,
                "item_name": item_name,
                "quantity": int(quantity),
            })

        for key, child in value.items():
            if key in {"required_supplies", "supplies_needed", "medical_supplies"} and isinstance(child, list):
                for item in child:
                    requirements.extend(extract_supply_requirements(item))
            elif isinstance(child, (dict, list)):
                requirements.extend(extract_supply_requirements(child))

    elif isinstance(value, list):
        for child in value:
            requirements.extend(extract_supply_requirements(child))

    return requirements


patients = get_json("/patients")
inventory = get_json("/inventory")
alerts = get_json("/alerts")

inventory_by_id = {item.get("item_id"): item for item in inventory if item.get("item_id")}
inventory_by_name = {
    item.get("name", "").casefold(): item
    for item in inventory
    if item.get("name")
}

# Aggregate explicitly recorded patient supply needs.
patient_demand = {}
for patient in patients:
    patient_id = patient.get("id")
    if not patient_id:
        continue

    records_response = session.get(
        f"{BASE_URL}/patients/{patient_id}/records",
        timeout=30,
    )
    if records_response.status_code == 404:
        continue
    records_response.raise_for_status()

    for requirement in extract_supply_requirements(records_response.json()):
        item = None
        if requirement["item_id"]:
            item = inventory_by_id.get(requirement["item_id"])
        if item is None and requirement["item_name"]:
            item = inventory_by_name.get(requirement["item_name"].casefold())
        if item is None:
            continue

        item_id = item["item_id"]
        patient_demand[item_id] = patient_demand.get(item_id, 0) + requirement["quantity"]

# Restock alert items to just above their stated thresholds. Include any
# explicitly identified patient demand when setting the updated quantity.
targets = {}
for alert in alerts:
    item = inventory_by_name.get(alert.get("item_name", "").casefold())
    if item is None:
        continue

    threshold = alert.get("quantity_threshold")
    current = item.get("quantity", 0)
    if isinstance(threshold, (int, float)):
        targets[item["item_id"]] = max(
            targets.get(item["item_id"], current),
            int(threshold) + 1,
        )

for item_id, demand in patient_demand.items():
    item = inventory_by_id[item_id]
    current = item.get("quantity", 0)
    targets[item_id] = max(targets.get(item_id, current), current + demand)

# Update only items with an active alert or a documented patient supply need.
for item_id, new_quantity in targets.items():
    item = inventory_by_id[item_id]
    if new_quantity <= item.get("quantity", 0):
        continue

    response = session.post(
        f"{BASE_URL}/inventory/update",
        json={"item_id": item_id, "new_quantity": new_quantity},
        timeout=30,
    )
    response.raise_for_status()

print({
    "patients_reviewed": len(patients),
    "inventory_items_reviewed": len(inventory),
    "active_alerts_reviewed": len(alerts),
    "inventory_updates": targets,
})

