def get_json(path):
    response = session.get(f"{BASE_URL}{path}", timeout=30)
    response.raise_for_status()
    return response.json()


def text_of(value):
    if isinstance(value, dict):
        return " ".join(text_of(v) for v in value.values())
    if isinstance(value, list):
        return " ".join(text_of(v) for v in value)
    return str(value) if value is not None else ""


def terms(value):
    ignored = {
        "the", "and", "for", "with", "from", "that", "this", "are", "was",
        "were", "into", "its", "has", "have", "may", "might", "could",
        "system", "equipment", "device", "threat", "risk", "security",
    }
    return {
        word for word in re.findall(r"[a-z0-9][a-z0-9._-]{2,}", text_of(value).lower())
        if word not in ignored
    }


def tracking_anomalies(value, path="$"):
    anomalies = []
    if isinstance(value, dict):
        for key, item in value.items():
            item_path = f"{path}.{key}"
            key_lower = str(key).lower()
            if key_lower in {"status", "health", "state"} and isinstance(item, str):
                if item.lower() not in {
                    "active", "online", "ok", "healthy", "operational", "normal", "running"
                }:
                    anomalies.append({"path": item_path, "value": item})
            anomalies.extend(tracking_anomalies(item, item_path))
    elif isinstance(value, list):
        for index, item in enumerate(value):
            anomalies.extend(tracking_anomalies(item, f"{path}[{index}]"))
    return anomalies


