BASE_URL = "https://api.socbench.example"
SPECIFIED_ZONE_IDS = []  # Set to the zone IDs that should be adjusted; empty selects all zones.
CRITICAL_DEMAND_THRESHOLD_MW = 1000.0
SUPPLY_RESERVE_FACTOR = 1.10
TIME_FRAME = "immediate"

session = requests.Session()

response = session.get(f"{BASE_URL}/realtime-demand", timeout=30)
response.raise_for_status()
demand_data = response.json()

zones = demand_data.get("zones", [])
demand_by_zone = {
    zone["zone_id"]: float(zone["demand"])
    for zone in zones
    if "zone_id" in zone and "demand" in zone
}

target_zone_ids = SPECIFIED_ZONE_IDS or list(demand_by_zone)
critical_zone_ids = {
    zone_id
    for zone_id, demand in demand_by_zone.items()
    if demand >= CRITICAL_DEMAND_THRESHOLD_MW
}

energy_saving_recommendations = [
    {
        "zone_id": zone_id,
        "priority": "high",
        "recommendation": (
            f"Review peak-load equipment and defer nonessential consumption; "
            f"current demand is {demand_by_zone[zone_id]:.1f} MW."
        ),
    }
    for zone_id in sorted(critical_zone_ids)
]

adjustment_results = []
for zone_id in target_zone_ids:
    if zone_id not in demand_by_zone:
        continue

    payload = {
        "zone_id": zone_id,
        "new_distribution_strategy": {
            "supply_limit": round(
                demand_by_zone[zone_id] * SUPPLY_RESERVE_FACTOR, 2
            ),
            "time_frame": TIME_FRAME,
        },
    }
    adjust_response = session.put(
        f"{BASE_URL}/adjust-distribution",
        json=payload,
        timeout=30,
    )
    adjust_response.raise_for_status()
    adjustment_results.append(
        {"zone_id": zone_id, "status_code": adjust_response.status_code}
    )

