import requests

BASE_URL = "https://api.socbench.example"
TIMEOUT = 30

# Store usage-alert settings as customizable billing-template parameters.
template_response = requests.post(
    f"{BASE_URL}/billing/templates",
    json={
        "template_name": "Utility Invoicing with Usage Alerts",
        "parameters": {
            "billing_cycle": "monthly",
            "usage_alerts_enabled": "true",
            "unusual_usage_threshold": "20% above baseline",
        },
    },
    timeout=TIMEOUT,
)
template_response.raise_for_status()
billing_template = template_response.json()

forecast_response = requests.get(
    f"{BASE_URL}/forecast-patterns", timeout=TIMEOUT
)
forecast_response.raise_for_status()
forecasts = forecast_response.json()

efficiency_response = requests.get(
    f"{BASE_URL}/efficiency-reports", timeout=TIMEOUT
)
efficiency_response.raise_for_status()
efficiency_reports = efficiency_response.json()

demand_response = requests.get(
    f"{BASE_URL}/realtime-demand", timeout=TIMEOUT
)
demand_response.raise_for_status()
realtime_demand = demand_response.json()

status_response = requests.get(
    f"{BASE_URL}/zones-status", timeout=TIMEOUT
)
status_response.raise_for_status()
zone_statuses = status_response.json()

# Rank operational zones by live demand, falling back to reported power usage.
demands_by_zone = {
    zone["zone_id"]: float(zone["demand"])
    for zone in realtime_demand.get("zones", [])
    if zone.get("zone_id") is not None and zone.get("demand") is not None
}
status_by_zone = {
    zone["zone_id"]: zone
    for zone in zone_statuses
    if zone.get("zone_id") is not None
}

for zone_id, zone in status_by_zone.items():
    if zone_id not in demands_by_zone and zone.get("power_usage") is not None:
        demands_by_zone[zone_id] = float(zone["power_usage"])

eligible_zones = []
for zone_id, demand in demands_by_zone.items():
    status = str(status_by_zone.get(zone_id, {}).get("status", "")).lower()
    if demand > 0 and not any(term in status for term in ("offline", "fault", "down")):
        eligible_zones.append((zone_id, demand))

# Allocate resources to the three highest-demand operational zones at high priority.
for zone_id, demand in sorted(eligible_zones, key=lambda item: item[1], reverse=True)[:3]:
    allocation_response = requests.post(
        f"{BASE_URL}/allocate-resources",
        json={
            "zone_id": zone_id,
            "allocated_power": demand,
            "priority": "high",
        },
        timeout=TIMEOUT,
    )
    allocation_response.raise_for_status()
